int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = 0;

    if (!page) {
        page = alloc_huge_page();
        if (!page) {
            return -ENOMEM;
        }
        *pagep = page;
    }

    if (!access_ok((void __user *)src_addr, HPAGE_PMD_SIZE)) {
        return -EFAULT;
    }

    if (copy_user_huge_page(page, (void __user *)src_addr, dst_addr, dst_vma, 0, HPAGE_PMD_NR)) {
        return -EFAULT;
    }

    set_page_dirty_lock(page);
    SetPageUptodate(page);

    pte_t entry = pte_mkold(pte_mkhuge(pte_mkdirty(pte_mkwrite(pte_set_page(pte_clear(pte_none(pte_val(*dst_pte)), page)))));
    set_pte_at(dst_mm, dst_addr, dst_pte, entry);
    arch_dup_mmap(NULL, NULL);

    if (dst_vma->vm_flags & VM_SHARED) {
        page->index = 0;
        page->private = 0;
    } else {
        get_page(page);
    }

    return ret;
}

#include <linux/mm.h>
#include <linux/hugepage.h>
#include <linux/vmalloc.h>

int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -ENOMEM;

    if (!page) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
        *pagep = page;
    }

    if (!access_ok((void __user *)src_addr, PAGE_SIZE))
        return -EFAULT;

    if (copy_from_user(page_address(page), (void __user *)src_addr, PAGE_SIZE))
        return -EFAULT;

    if (dst_vma->vm_flags & VM_SHARED) {
        ret = 0;
    } else {
        page = split_huge_page(page);
        if (IS_ERR(page))
            return PTR_ERR(page);
        *pagep = page;
    }

    pte_t pte = mk_pte(page, dst_vma->vm_page_prot);
    set_pte_at(dst_mm, dst_addr, dst_pte, pte);
    flush_tlb_page(dst_vma, dst_addr);

    return 0;
}

int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -EFAULT;

    if (!page) {
        page = alloc_huge_page();
        if (!page)
            return -ENOMEM;
        *pagep = page;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_PMD_SIZE)) {
        put_page(page);
        *pagep = NULL;
        return -EFAULT;
    }

    if (dst_vma->vm_flags & VM_SHARED) {
        set_page_dirty(page);
    } else {
        set_page_private(page);
    }

    spin_lock(&dst_mm->page_table_lock);
    set_pte(dst_pte, mk_pte(page, dst_vma->vm_page_prot));
    spin_unlock(&dst_mm->page_table_lock);

    return 0;
}

int copy_huge_page_entry(struct mm_struct *dst_mm, pte_t *dst_pte,
                         struct vm_area_struct *dst_vma, unsigned long dst_addr,
                         unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = 0;

    if (!page) {
        page = alloc_huge_page();
        if (!page) {
            return -ENOMEM;
        }
        *pagep = page;
    }

    if (!access_ok(VERIFY_READ, (void __user *)src_addr, PAGE_SIZE)) {
        return -EFAULT;
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, PAGE_SIZE)) {
        return -EFAULT;
    }

    if (dst_vma->vm_flags & VM_SHARED) {
        set_page_count(page, 2);
    } else {
        set_page_count(page, 1);
    }

    set_pte(dst_pte, pte_mkhuge(mk_pte(page, dst_vma->vm_page_prot)));
    arch_set_huge_pte(dst_vma, dst_pte, page, dst_addr);

    return ret;
}
